import{_ as t,c as d,o as e,a4 as r}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q3：<script> 标签的 async 与 defer 有什么区别？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q3.md","filePath":"frontend/q3.md","lastUpdated":null}'),o={name:"frontend/q3.md"},a=r('<h1 id="q3-script-标签的-async-与-defer-有什么区别" tabindex="-1">Q3：<code>&lt;script&gt;</code> 标签的 async 与 defer 有什么区别？ <a class="header-anchor" href="#q3-script-标签的-async-与-defer-有什么区别" aria-label="Permalink to &quot;Q3：`&lt;script&gt;` 标签的 async 与 defer 有什么区别？&quot;">​</a></h1><p>解析 HTML 时，遇到普通 <code>&lt;script&gt;</code> 会停止解析，下载并执行 JS，执行完再继续解析。<code>async</code> 和 <code>defer</code> 改变了这一行为。</p><table><thead><tr><th>类型</th><th>下载时机</th><th>执行时机</th><th>执行顺序</th><th>对解析阻塞</th></tr></thead><tbody><tr><td><strong>无属性</strong></td><td>立即下载</td><td>下载后立即执行</td><td>文档中顺序</td><td>阻塞解析，直到执行完</td></tr><tr><td><strong>defer</strong></td><td>立即下载，异步</td><td>在 HTML 解析完成后，<code>DOMContentLoaded</code> 事件前执行</td><td>按文档顺序执行</td><td>不阻塞解析</td></tr><tr><td><strong>async</strong></td><td>立即下载，异步</td><td>下载完成后立即执行，可能在任何时刻</td><td>无法保证顺序，谁先下完谁执行</td><td>执行时会阻塞解析</td></tr></tbody></table><ul><li><code>defer</code> 适用于互相依赖且需要操作 DOM 的脚本，确保在 DOM 构建完毕后按顺序执行。</li><li><code>async</code> 适合独立脚本，如统计、广告，不需要依赖其他脚本和 DOM 结构。</li></ul>',4),c=[a];function n(s,i,l,_,h,f){return e(),d("div",null,c)}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
